const leftPosition = new Vector3(-10.7, -1, 0.0)

const calcPosition = (pos: Vector3) => {
  pos.add(leftPosition)
  pos.x *= 1.0 + CORNER_RADIUS
  pos.y *= 1.0 + CORNER_RADIUS
  pos.z *= 1.0 + CORNER_RADIUS

  return pos
}

