const valley = (x: number) => {
  return Math.abs(2 * x - 1)
}

cubes.forEach((cube, index) => {
  const p = index / (cubes.length - 1)
  cube.delay = valley(p)
  cube.duration = 1
})

export default {
  rotation: new Vector3(Math.PI * 0.25, -Math.PI * 0.2, 0),
  rotationOrder: 'YXZ',
  groupAnim: {
    start: new Vector3(0, -0.5, 0),
    end: new Vector3(0, 0, 0),
    duration: 4.0,
    ease: 'expo.out',
  },
  cubes,
} as LayoutConfig
